const app = document.querySelector('#app');
const arrow = '<svg viewBox="0 0 80 40" aria-hidden="true"><path d="M2 7C13 32 46 7 69 24M59 16l11 9-14 5" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
function preview(c,i){return `<a class="concept-card theme-${c.id}" href="#/concept/${c.id}" aria-label="Explore concept ${i+1}: ${c.name}"><div class="card-preview"><div class="preview-scene"><svg viewBox="0 0 380 250" preserveAspectRatio="none" aria-hidden="true"><path class="accent" d="${c.path}"/><path class="accent" d="M286 226l8 12 10-11"/>${c.id==='atlas'?'<path opacity=".15" d="M-20 180C140 200 15 15 198 13S400 80 398 199M-20 193C162 211 26 24 196 24S392 81 408 211M-20 204C182 220 40 34 196 36S380 87 416 224"/>':''}${c.id==='orbit'?'<circle cx="183" cy="124" r="107" opacity=".14"/><circle cx="333" cy="73" r="4"/><path d="M49 58v14m-7-7h14"/>':''}</svg><img class="preview-logo" src="assets/northstate-logo.svg" alt=""><div class="preview-title">${c.title.replace('\n','<br>')}</div><div class="preview-node">${['Made to endure','FINISH / 02','PROTECT. REFINE.','An honest craft.','POWDER COATING','A little possibility','Burlington, NC','THE NEXT CHAPTER','Care in every coat','A lasting connection'][i]}</div><span class="preview-caption">NORTH STATE · ${String(i+1).padStart(2,'0')}</span></div><div class="preview-open"><span>Follow this line ↗</span></div></div><div class="card-label"><span class="card-title"><span class="card-number">${String(i+1).padStart(2,'0')}</span>${c.name}</span><span class="card-arrow" aria-hidden="true">↗</span></div><p class="card-description">${c.tag}</p></a>`}
function renderHub(){document.body.className='';document.title='North State — A study in flow';app.innerHTML=`<div class="hub"><header class="hub-header"><span class="eyebrow">A study in flow<br>Web concept collection</span><img src="assets/northstate-logo.svg" alt="North State Powder Coating"><span class="edition mono">Ten directions<br>One North State</span></header><main id="main"><section class="hub-intro"><h1>Good things<br>follow <em>a line.</em></h1><div class="intro-copy"><p>A different kind of website for North State.<br>Less grid. More journey. Ink, paper, and ideas that find their own way.</p><div class="intro-note">Pick a direction. See where it goes. ${arrow}</div></div></section><div class="collection-line"><span class="eyebrow">The explorations / 01—10</span><span>Open a concept & scroll to draw</span></div><div class="concept-grid">${concepts.map(preview).join('')}</div></main><footer class="hub-footer"><span>NORTH STATE POWDER COATING · Burlington, North Carolina</span><span>Concept studies · Business details from <a href="https://northstatepc.com/" target="_blank" rel="noreferrer">northstatepc.com ↗</a></span></footer></div>`}
function route(){if(window.cleanupConcept)window.cleanupConcept();window.scrollTo({top:0,behavior:'instant'});const id=location.hash.split('/')[2];const c=concepts.find(c=>c.id===id);if(c && window.renderConcept)window.renderConcept(c,concepts.indexOf(c));else renderHub()}
document.querySelector('.skip-link').addEventListener('click',event=>{event.preventDefault();const main=document.querySelector('#main');main.setAttribute('tabindex','-1');main.focus({preventScroll:true});main.scrollIntoView({behavior:'instant'});});
window.addEventListener('hashchange',route);route();
